import pathlib,subprocess,socket,time,re,json,os,secrets
assert os.getuid()!=0
before=subprocess.check_output(['ip','-j','route','show','table','all'])
ports=[];reserved=[]
for _ in range(2):
    s=socket.socket();s.bind(('127.0.0.1',0));ports.append(s.getsockname()[1]);reserved.append(s)
for s in reserved:s.close()
k=secrets.randbelow(150)+1
oldprefix=f'198.18.{k}.0/24';newprefix=f'198.19.{k}.0/24';unrelated=f'203.0.113.{secrets.randbelow(250)+1}/32'
def sender(selected):
    return f"""
log stderr all;
router id 192.0.2.1;
protocol static seed {{ ipv4; route {oldprefix} blackhole; route {newprefix} blackhole; route {unrelated} blackhole; }}
protocol bgp peer {{
 local 127.0.0.1 port {ports[0]} as 65001; neighbor 127.0.0.1 port {ports[1]} as 65002;
 multihop; strict bind on; connect retry time 1; connect delay time 1; error wait time 1,2;
 ipv4 {{ import none; next hop keep; export filter {{ if net ~ [{selected},{unrelated}] then {{ bgp_next_hop=192.0.2.254; accept; }} reject; }}; }};
}}
"""
receiver=f"""
log stderr all; router id 192.0.2.2;
protocol static igp {{ ipv4; route 192.0.2.254/32 blackhole; }}
protocol bgp peer {{
 local 127.0.0.1 port {ports[1]} as 65002; neighbor 127.0.0.1 port {ports[0]} as 65001;
 multihop; passive on; strict bind on; connect retry time 1; connect delay time 1;
 ipv4 {{ import all; export none; }};
}}
"""
pathlib.Path('sender.conf').write_text(sender(oldprefix));pathlib.Path('candidate.conf').write_text(sender(newprefix));pathlib.Path('receiver.conf').write_text(receiver)
snapshots={name:pathlib.Path(name).read_bytes() for name in ('sender.conf','receiver.conf')}
processes=[];handles=[]
def routes():
    result=subprocess.run(['birdc','-s','receiver.ctl','show','route','protocol','peer','all'],capture_output=True,text=True,timeout=2)
    assert result.returncode==0,result.stdout+result.stderr
    return set(re.findall(r'(?m)^(\d+\.\d+\.\d+\.\d+/\d+)\s',result.stdout)),result.stdout
def wait_routes(expected,seconds=5):
    end=time.monotonic()+seconds;last=None
    while time.monotonic()<end:
        assert all(p.poll() is None for p in processes)
        last=routes()
        if last[0]==expected:return last[1]
        time.sleep(.03)
    raise AssertionError({'expected':sorted(expected),'actual':last})
def script(name):
    return subprocess.run(['bash',name],capture_output=True,text=True,timeout=3)
try:
    for name in ('receiver','sender'):
        h=open(name+'.log','w');handles.append(h)
        processes.append(subprocess.Popen(['bird','-f','-c',name+'.conf','-s',name+'.ctl','-P',name+'.pid'],stdout=h,stderr=h))
    for _ in range(100):
        if all(pathlib.Path(n+'.ctl').exists() for n in ('sender','receiver')):break
        assert all(p.poll() is None for p in processes);time.sleep(.01)
    baseline=wait_routes({oldprefix,unrelated})
    result=script('stage.sh');assert result.returncode==0,result.stdout+result.stderr
    staged=wait_routes({newprefix,unrelated},2)
    rolled_back=wait_routes({oldprefix,unrelated},4)
    result=script('stage.sh');assert result.returncode==0,result.stdout+result.stderr
    wait_routes({newprefix,unrelated},2)
    result=script('commit.sh');assert result.returncode==0,result.stdout+result.stderr
    # A confirmed change must remain after the 3-second rollback deadline.
    time.sleep(3.4);confirmed=wait_routes({newprefix,unrelated},1)
    pathlib.Path('candidate.conf').write_text('this is a broken BIRD config;\n')
    result=script('stage.sh');assert result.returncode!=0,'syntax-invalid candidate must fail'
    preserved=wait_routes({newprefix,unrelated},1)
    assert all(pathlib.Path(n).read_bytes()==v for n,v in snapshots.items()),'operator scripts must not overwrite baseline or peer configuration'
    pathlib.Path('change-observations.json').write_text(json.dumps({'baseline':baseline,'staged':staged,'automatic_rollback':rolled_back,'confirmed':confirmed,'invalid_preserved':preserved,'production_convergence_claim':False},indent=2))
finally:
    for p in processes:
        if p.poll() is None:p.terminate()
    for p in processes:
        try:p.wait(timeout=2)
        except subprocess.TimeoutExpired:p.kill();p.wait(timeout=2)
    for h in handles:h.close()
    assert before==subprocess.check_output(['ip','-j','route','show','table','all'])
